Add a method to return collection metrics like:
```python

def get_collection_metrics(self, collection_name):
        """
        Aggregates key dashboard metrics for a specific collection.
        """
        if not self.connected:
            return {"error": "Not connected to Milvus"}


        if not utility.has_collection(collection_name, using=self.alias):
            return {"error": f"Collection '{collection_name}' not found"}


        try:
            # Load Collection Object
            col = Collection(collection_name, using=self.alias)
            
            # 1. Basic Counts
            # Note: num_entities is approximate (based on sealed segments). 
            # For exact real-time count including growing segments, query count(*) is needed but slower.
            row_count = col.num_entities 
            
            # 2. Load State (Is it in memory?)
            load_state = utility.load_state(collection_name, using=self.alias)
            loading_progress = utility.loading_progress(collection_name, using=self.alias)


            # 3. Index Status
            index_infos = []
            for index in col.indexes:
                # progress returns {'total_rows': X, 'indexed_rows': Y}
                progress = utility.index_building_progress(collection_name, index_name=index.index_name, using=self.alias)
                index_infos.append({
                    "field": index.field_name,
                    "index_name": index.index_name,
                    "indexed_rows": progress.get('indexed_rows', 0),
                    "total_rows": progress.get('total_rows', 0),
                    "params": index.params
                })


            # 4. Segment Info (Advanced System Health)
            # Useful to see how data is distributed across Query Nodes
            segment_info = utility.get_query_segment_info(collection_name, using=self.alias)
            total_segments = len(segment_info)
            
            return {
                "collection": collection_name,
                "row_count": row_count,
                "status": {
                    "load_state": str(load_state),
                    "loading_progress": loading_progress.get('loading_progress', '0%')
                },
                "schema": {
                    "description": col.description,
                    "fields": [f.name for f in col.schema.fields],
                    "primary_key": col.primary_field.name
                },
                "indexes": index_infos,
                "segments": {
                    "total_active_segments": total_segments,
                    # Calculate total memory usage if available in your version's segment info
                    "details_available": True if total_segments > 0 else False
                }
            }


        except MilvusException as e:
            return {"error": str(e)}
```
